t.script:
function ehChooseFriend(btn) {
    var chooser = document.getElementById('eh_referral_friend_chooser');
    chooser.classList.add('o_eh_referral_chooser_busy');
    fetch('/eh/referral/choose_avatar', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: {
            applicant_id: parseInt(chooser.dataset.applicantId),
            friend_id: parseInt(btn.dataset.friendId),
        } })
    }).then(function() { window.location.reload(); })
      .catch(function() { chooser.classList.remove('o_eh_referral_chooser_busy'); });
}

var ehCurrentSlide = 0;
var ehTotalSlides = 4;

function ehGoToSlide(n) {
    if (n < 0 || n >= ehTotalSlides) return;
    ehCurrentSlide = n;
    var slides = document.querySelectorAll('.eh_slide');
    var dots = document.querySelectorAll('.eh_dot');
    for (var i = 0; i < slides.length; i++) {
        if (i === ehCurrentSlide) {
            slides[i].classList.add('active');
            if (dots[i]) dots[i].classList.add('active');
        } else {
            slides[i].classList.remove('active');
            if (dots[i]) dots[i].classList.remove('active');
        }
    }
    var nextBtn = document.getElementById('eh_btn_next');
    if (nextBtn) {
        if (ehCurrentSlide === ehTotalSlides - 1) {
            nextBtn.textContent = 'Start >';
        } else {
            nextBtn.textContent = 'Next >';
        }
    }
}

function ehNextOnboardingSlide() {
    if (ehCurrentSlide < ehTotalSlides - 1) {
        ehGoToSlide(ehCurrentSlide + 1);
    } else {
        ehSkipOnboarding();
    }
}

function ehSkipOnboarding() {
    try {
        fetch('/eh/referral/onboarding_skip', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: {} })
        }).catch(function() {
            fetch('/eh/referral/onboarding_skip_http', { method: 'POST' });
        });
    } catch(e) {
        // ignore network error
    }
    var modal = document.getElementById('eh_referral_onboarding_modal');
    if (modal) {
        modal.classList.add('eh_fade_out');
        setTimeout(function() {
            modal.style.display = 'none';
            modal.classList.remove('eh_fade_out');
            var chooser = document.getElementById('eh_referral_friend_chooser');
            if (chooser) chooser.style.display = 'flex';
        }, 450);
    }
}

function ehRestartOnboarding() {
    var modal = document.getElementById('eh_referral_onboarding_modal');
    if (modal) {
        modal.style.display = 'flex';
        modal.classList.remove('eh_fade_out');
        ehGoToSlide(0);
    }
}

// Keyboard arrow navigation
window.addEventListener('keydown', function(e) {
    var modal = document.getElementById('eh_referral_onboarding_modal');
    if (!modal || modal.style.display === 'none') return;
    if (e.key === 'ArrowRight') {
        ehNextOnboardingSlide();
    } else if (e.key === 'ArrowLeft') {
        if (ehCurrentSlide > 0) ehGoToSlide(ehCurrentSlide - 1);
    } else if (e.key === 'Escape') {
        ehSkipOnboarding();
    }
});
